function normalizeAmmoItemId(id) {
  const key = String(id || "").trim().toLowerCase();
  if (!key) return "";
  if (key === "arrows") return "ammo_arrows";
  if (key === "fire_arrows") return "ammo_fire_arrows";
  if (key === "piercing_arrows") return "ammo_piercing_arrows";
