];
const _CORPSE_SKIP_KEYS = new Set([
  'gold', 'monster', 'bone', 'engraving', 'spawner', 'tombstone',
  'chest', 'mill_chest', 'smithy_chest', 'lumber_chest', 'herb_chest', 'tavern_chest',
